// Three Integrated Strategies mid-bosses, one contract each:
// - Lost Colossus (enemy_2003_rockman): a melee brawler that throws a rock (70% ATK Physical, a 25 s Stun) at an
//   operator within 2.5 that is not Stunned already, every 13 s.
// - Jetman (enemy_2004_balloon): every 25 s (first after 1 s) he arms a take-off; the next time he is blocked he
//   becomes a block-free aerial unit for 7 s with +50% move speed and no attacks.
// - Wandering Puppet (enemy_2013_csbot): while not blocked, every operator on the map takes 100 Arts damage per second.
// Every component reachable from the retained abilities, the templates and the rock projectile are pinned below with
// local references reduced to null/local.
import colossusClocks from "../../data/arkpedia-lost-colossus-animations.json" with{type:"json"};
import jetmanClocks from "../../data/arkpedia-jetman-animations.json" with{type:"json"};
import puppetClocks from "../../data/arkpedia-wandering-puppet-animations.json" with{type:"json"};
import {sameOutcomeValue as same} from "./enemy-outcome-contracts.js";
export const isLostColossus=r=>r?.prefabKey==="enemy_2003_rockman";
export const isJetman=r=>r?.prefabKey==="enemy_2004_balloon";
export const isWanderingPuppet=r=>r?.prefabKey==="enemy_2013_csbot";
const norm=v=>Array.isArray(v)?v.map(norm):v&&typeof v==="object"?("m_PathID"in v&&Object.keys(v).length===2?{ref:v.m_PathID==="0"?null:v.m_FileID===0?"local":"ext:"+v.m_PathID}
 :Object.fromEntries(Object.entries(v).filter(([k])=>!["m_GameObject","m_Name","m_Father","m_Children"].includes(k)).map(([k,x])=>[k,norm(x)]))):v;
const refs=v=>Array.isArray(v)?v.flatMap(refs):v&&typeof v==="object"?("m_PathID"in v&&v.m_FileID===0&&v.m_PathID!=="0"&&Object.keys(v).length===2?[v]
 :Object.entries(v).filter(([k])=>k!=="m_GameObject").flatMap(([,x])=>refs(x))):[];
function closure(n){
 const seen=new Set(),todo=Object.values(n).flat();
 while(todo.length){const c=todo.pop();if(!c||seen.has(c))continue;seen.add(c);todo.push(...n.$siblings(c),...refs(c).map(r=>n.$ref(r)).filter(Boolean));}
 return [...seen].map(c=>JSON.stringify(norm(c))).sort();
}
const f32=Math.fround;
const NO_TALENTS={"bb":{},"bbStr":{},"groups":{}};
/** One record, its pinned native tree and its clip clocks. */
function contract(spec){
 return (r,n)=>{
  if(r?.prefabKey!==spec.prefabKey||r.level!==0||r.applyWay!=="MELEE"||r.stats.rangeRadius!==0||r.stats.bat!==spec.bat||r.stats.blockCnt!==1||r.notCountInTotal
   ||Object.entries(spec.stats).some(([k,v])=>r.stats[k]!==v)||!same(r.abilities,spec.abilities)||!same(r.talents,spec.talents)||!same(r.skills,spec.skills))return false;
  if(!same(closure(n),spec.components)||Object.entries(spec.templates).some(([k,v])=>!same(n.$template(k),v))
   ||Object.entries(spec.projectiles).some(([k,v])=>!same(n.$projectile(k).map(c=>JSON.stringify(norm(c))).sort(),v)))return false;
  const root=n[r.prefabKey]?.find(v=>"_modes"in v),graphic=n.$ref(root?._animator),clock=spec.clocks.enemies[r.prefabKey];
  return !!clock&&n.$ref(graphic?._skeleton)?.skeletonDataAsset?.m_PathID===clock.source?.skeletonDataPathId
   &&Object.entries(spec.clock.durations).every(([k,v])=>clock.durations[k]===v)
   &&Object.entries(spec.clock.events).every(([k,v])=>same(clock.events[k]?.filter(x=>x.name==="OnAttack").map(x=>x.time),v));
 };
}

