/** Runtime parameters from the skill, the pinned components and the clips. */
export function lostColossusParams(r){
 const s=r.skills.find(x=>x.prefabKey==="StunAttack");
 return {
  // Combat: the melee attack at the Attack clip's event.
  attack:{anim:{dur:ROCKMAN_CLOCK.durations.Attack,hit:ROCKMAN_CLOCK.events.Attack[0]}},
  // StunAttack: one operator (ground or aerial) within the 2.5 trigger that has no Stun; the Skill clip's event launches
  // the speed-10 projectile_enemy_rockman: atk_scale x ATK Physical and the database stun for `stun` s.
  rock:{cooldown:s.cooldown,initial:s.initCooldown,range:2.5,scale:s.bb.atk_scale,stun:s.bb.stun,speed:10,
   anim:{dur:ROCKMAN_CLOCK.durations.Skill,hit:ROCKMAN_CLOCK.events.Skill[0]}},
 };
}

// ---- Jetman ----
export const JETMAN_ABILITIES=[{"text":"When blocked, this unit will take off for a period of time (this effect has a cooldown)","format":"NORMAL"}];
