export function wanderingPuppetParams(r){
 return {
  // Blocked (the block checker, at least one blocker), he switches to the Combat mode and attacks with the Attack clip.
  attack:{anim:{dur:CSBOT_CLOCK.durations.Attack,hit:CSBOT_CLOCK.events.Attack[0]}},
  // The Default mode's Poison: every opposing unit on the map gets enemy_csbot_t (enemy_toxcar_t: no-source Arts damage
  // `poison.damage` every 1 s, the first after 1 s); it is removed when the ability detaches (blocked, defeated).
  poison:{damage:r.talents.bb["poison.damage"],interval:1},
 };
}

